  void _wireImageCapLearnedNotice() {
    imageCapLearnedNotice = (modelId, cap) {
      io.writeln(
        _style.dim(
          '[images] provider refused: too many images for $modelId — '
          'cap learned: $cap; re-sending with fewer images',
        ),
      );
      _logDiagnostic('image cap learned sid=$_logSid model=$modelId cap=$cap');
    };
  }

---
  /// The model id from the refusal text (`maximum allowed for model
  /// gemini-4-argon is 10` → `gemini-4-argon`).
  final String modelId;

  /// The cap the provider announced. May be garbage (< 1) — the caller
  /// guards before latching/re-sending (edge E3).
  final int learnedCap;
}

