    final applied = _repinRolesChain(
      resolver: config.modelRolesResolver!,
      spec: spec,
      built: built,
      entry: entry,
      key: key,
      previous: previous,
    );
    if (!applied) return;
  } else {
    _streamFunction = _catalogStreamFunction(spec.kind, key);
    _agent.streamFunction = _streamFunction;
  }

