      builds++;
      if (builds == 2) {
        return [
          ...messages,
          UserMessage(
            content: [ImageContent(data: 'late', mimeType: 'image/png')],
            timestamp: DateTime.utc(2026, 1, 2),
          ),
        ];
      }
      return messages;
    }

    final messages = await runAgentLoop(
