    required CustomProviderEntry? entry,
  }) {
    try {
      return buildCliDefaultModel(
        providerKind,
        modelId: modelId,
        baseUrl: baseUrl,
        authHeader:
            entry?.authHeader ??
            authHeaderForBaseUrl(
              config.customProviders?.entries ?? const [],
              baseUrl,
            ),
      );
    } on ConfigException {
      io.writeln(
        _style.dim(
